import java.util.StringTokenizer
import kotlin.math.abs

fun main() {
    val br = System.`in`.bufferedReader()
    var st = StringTokenizer(br.readLine())
    var xo = st.nextToken().toLong()
    var yo = st.nextToken().toLong()
    val ax = st.nextToken().toLong()
    val ay = st.nextToken().toLong()
    val bx = st.nextToken().toLong()
    val by = st.nextToken().toLong()
    val orx = xo
    val ory = yo

    st = StringTokenizer(br.readLine())
    val xs = st.nextToken().toLong()
    val ys = st.nextToken().toLong()
    val t = st.nextToken().toLong()

    var cur = abs(xo - xs) + abs(yo - ys)
    val sort = mutableListOf<Long>()
    sort.add(cur)
    while (true) {
        var x = xo
        var y = yo
        xo = ax * xo + bx
        yo = ay * yo + by
        cur = abs(xo - xs) + abs(yo - ys)
        if (cur > sort.last()) {
            break
        } else {
            sort.add(cur)
        }
    }

    var dpoint = 0
    var copyx = xo
    var copyy = yo
    var mina = abs(xo - xs) + abs(yo - ys)
    if (mina <= t) {
        dpoint += 1
    }
    var time = 0L
    var copy = time
    var x = xo
    var y = yo
    while (time < t && !(x == orx && y == ory)) {
        val a = x
        val b = y
        x = (x - bx) / ax
        y = (y - by) / ay
        time += abs(x - a) + abs(y - b)
        if (time + minOf(mina, abs(x - xs) + abs(y - ys)) <= t) {
            dpoint += 1
        }
    }
    if (time + minOf(mina, abs(x - xs) + abs(y - ys)) < t) {
        mina = abs(x - xs) + abs(y - ys)
        while (time < t) {
            val a = ax * copyx + bx
            val b = ay * copyy + by
            time += abs(a - copyx) + abs(b - copyy)
            copyx = a
            copyy = b
            x = a
            y = b
            if (time + minOf(mina, abs(a - xs) + (b - ys).let { abs(it) })) <= t) {
                dpoint += 1
            }
        }
    }
    println(dpoint)
}

